check("Connections: a call into a sandbox asks the API for a connection, then goes to its server with the connection's token", async () => {
  const { api, connects, served } = servers(undefined, undefined, { workspace: "w1" });
  await into(api, "s1");

  const [asked] = connects();
  assert.equal(asked?.headers.get("Authorization"), `Bearer ${token}`);
  const named = { sandboxId: "s1" };
  const request = toBinary(w.ConnectSandboxRequestSchema, create(w.ConnectSandboxRequestSchema, named));
  assert.deepStrictEqual(asked?.body, request, "the connection was asked for with other fields than the sandbox");

  const [call] = served();
  assert.equal(call?.headers.get("Authorization"), `Bearer ${connectionToken}`);
  const reached = sent(served(), "RunCommand", w.RunCommandRequestSchema)[0];
  assert.equal(reached?.sandboxId, "s1");
});

check("Connections: two calls into one sandbox connect once, and another sandbox once more", async () => {
  const { api, connects, served } = servers();
  await into(api, "s1");
  await into(api, "s1");
  await into(api, "s2");

  const asked = connects().map((call) => fromBinary(w.ConnectSandboxRequestSchema, call.body).sandboxId);
  assert.deepStrictEqual(asked, ["s1", "s2"]);
  assert.equal(served().length, 3);
});

check("Connections: a connection 60 s or less from its expiry is not used again", async () => {
  const soon = connection({ expireTime: timestampFromMs(Date.now() + (60 - 1) * 1000) });
  const { api, connects, served } = servers(undefined, (call) => (call.url === connectUrl ? answer(w.ConnectionSchema, soon) : empty));
  await into(api, "s1");
  await into(api, "s1");

  assert.equal(connects().length, 2);
  assert.equal(served().length, 2);
});

check("Connections: a connection the API refuses is the call's error", async () => {
  const { api, served } = servers(undefined, (call) => (call.url === connectUrl ? refusal(403, "permission_denied", "not granted") : empty));
  const error = await rejection(into(api, "s1"));

  assert.equal(error.code, "PERMISSION_DENIED");
  assert.equal(served().length, 0);
});

check("Connections: UNAUTHENTICATED at a kept connection connects again and repeats the call once, as it was", async () => {
  const { api, connects, served } = servers((n) => (n === 1 ? refusal(401, "unauthenticated", "refused") : empty));
  await into(api, "s1");
  await into(api, "s1");

  assert.equal(connects().length, 2);
  const [, refused, repeated] = served();
  assert.equal(served().length, 3);
  assert.deepStrictEqual(repeated?.body, refused?.body, "the call was repeated with another request");
  const [, id] = sent(served(), "RunCommand", w.RunCommandRequestSchema).map((request) => request.requestId);
  assert.match(id ?? "", filledId);
});

